/* From Uiverse.io by ozgeozkaraa01 - Tags: button, radio, hover button */
.__UIV_SCOPE__ .container {
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #f2f2f2;
}

.__UIV_SCOPE__ .custom-radio {
  display: flex;
  flex-direction: column;
  background-color: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  overflow: hidden;
}

.__UIV_SCOPE__ .custom-radio input[type="radio"] {
  display: none;
}

.__UIV_SCOPE__ .radio-label {
  display: flex;
  align-items: center;
  padding: 10px 20px;
  cursor: pointer;
  transition: background-color 0.3s ease-in-out;
}

.__UIV_SCOPE__ .radio-circle {
  width: 20px;
  height: 20px;
  border: 2px solid #ffcc00;
  border-radius: 50%;
  margin-right: 10px;
  transition: border-color 0.3s ease-in-out, background-color 0.3s ease-in-out;
}

.__UIV_SCOPE__ .radio-text {
  font-size: 1rem;
  color: #333;
  transition: color 0.3s ease-in-out;
}

.__UIV_SCOPE__ .custom-radio input[type="radio"]:checked + .radio-label {
  background-color: #ffcc00;
}

.__UIV_SCOPE__ .custom-radio input[type="radio"]:checked + .radio-label .radio-circle {
  border-color: #fff;
  background-color: #ffcc00;
}

.__UIV_SCOPE__ .custom-radio input[type="radio"]:checked + .radio-label .radio-text {
  color: #64748b;
}
